{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Isradipine, a lipophilic dihydropyridine with poor aqueous solubility and extensive first-pass metabolism, has systemic availability of only 17% in healthy volunteers, below the 20% threshold; this supports low F for the similarly lipophilic, poorly soluble quinone query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Pentazocine, a lipophilic drug subject to extensive first-pass metabolism, has absolute oral bioavailability of 18% in healthy subjects, below the threshold; this supports low F for the query, which is even more lipophilic and much larger.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Rigosertib in the fed state has absolute oral bioavailability of 13.9%, below the threshold, demonstrating that a poorly soluble, high-dose lipophilic drug can fall below 20% under absorption-limiting conditions; the query's very long lipophilic polyprenyl chain is expected to be at least as absorption-limited.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Nifedipine, a related dihydropyridine with extensive first-pass metabolism, has oral bioavailability of about 45% in humans, above the threshold; this is contradictory evidence that lipophilic, first-pass-metabolized drugs can still exceed 20%, but nifedipine is much smaller and less lipophilic than the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a highly lipophilic, high-molecular-weight polyprenyl quinone (CoQ10-type) with very poor aqueous solubility. Transferable evidence from lipophilic, first-pass-metabolized drugs with low oral bioavailability supports F <20%, while the few high-F analogues are less applicable due to smaller size and different absorption characteristics.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule or a close polyprenyl quinone analogue.",
    "The supplied evidence molecules are structurally distant smaller drugs, so transferability relies on physicochemical analogy rather than direct scaffold match.",
    "Food and formulation effects, which strongly modulate CoQ10-type absorption, are not directly captured for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

